const input = $input.first().json;
if (!input.message || !input.message.text) return [];

const text = input.message.text.trim();
const senderId = input.message.from.id;

// Tus IDs reales
const lau_id = 1923692633;
const cholo_id = 7283795641;

// -- SEGURIDAD --
if (senderId !== lau_id && senderId !== cholo_id) return [];

const isLau = (senderId === lau_id);
const senderName = isLau ? "Lau" : "Cholo";
const otherName = isLau ? "Cholo" : "Lau";

// Zona horaria robusta para Buenos Aires (evita errores a fin de mes)
const optionsTZ = { timeZone: 'America/Argentina/Buenos_Aires' };
const formatterMonth = new Intl.DateTimeFormat('es-AR', { ...optionsTZ, month: 'long' });
const formatterYear = new Intl.DateTimeFormat('es-AR', { ...optionsTZ, year: 'numeric' });
const formatterDate = new Intl.DateTimeFormat('es-AR', { ...optionsTZ, day: '2-digit', month: '2-digit', year: 'numeric' });

const act = new Date();
const mes_nombre = formatterMonth.format(act).toLowerCase();
const anio = formatterYear.format(act);
const mes_periodo = `${mes_nombre}-${anio}`;
const fecha = formatterDate.format(act);
const chatId = input.message.chat.id;

return [{
  json: {
    senderId: senderId,
    senderName: senderName,
    otherName: otherName,
    fecha: fecha,
    mes_periodo: mes_periodo,
    chatId: chatId,
    messageText: text
  }
}];

try {
  const rawStr = $input.first().json.text;
  const cleanStr = rawStr.replace(/```json/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleanStr);
  return { json: { ...$input.first().json, extraccion: parsed } };
} catch(e) {
  return { json: { error: "Fallo el parseo JSON del LLM", raw: $input.first().json.text } };
}

const balanceData = $input.first().json;

// Extracción simple desde la pestaña Balance de Google Sheets
const totalHistorico = balanceData.Gasto_Total_Historico || 0;
const deudaNeta = balanceData.Deuda_Neta || 0;
const quienDebe = balanceData.Quien_Debe || 'Nadie';

let balanceString = 'Están hechos, nadie le debe a nadie.';
if (quienDebe === 'Cholo') {
    balanceString = `Cholo le debe a Lau $${parseFloat(deudaNeta).toFixed(2)}`;
} else if (quienDebe === 'Lau') {
    balanceString = `Lau le debe a Cholo $${parseFloat(deudaNeta).toFixed(2)}`;
}

return { json: { \n  balance: balanceString, \n  total_historico: parseFloat(totalHistorico).toFixed(2), \n  accion: "ver_balance"\n} };
